  #ui {
    position:fixed; inset:0; display:flex; align-items:center; justify-content:center;
    font-family:'Press Start 2P', monospace; color:#fff; pointer-events:none; z-index:10;
  }
  .panel {
    pointer-events:auto; text-align:center; background:rgba(20,24,40,.92);
    border:4px solid #fff; box-shadow:8px 8px 0 rgba(0,0,0,.5); padding:36px 44px;
  }
  .panel h1 { font-size:28px; margin-bottom:18px; color:#ffd23f; text-shadow:3px 3px 0 #b3541e; }
  .panel p { font-size:10px; line-height:1.9; margin-bottom:8px; }
  .panel .big { font-size:14px; color:#7CFC00; margin:14px 0; }
  .btn {
    font-family:inherit; font-size:12px; color:#000; background:#ffd23f; border:none;
    padding:14px 26px; margin-top:14px; cursor:pointer; box-shadow:4px 4px 0 #b3541e;
  }
  .btn:active { transform:translate(4px,4px); box-shadow:none; }
  .hidden { display:none !important; }
</style>
